-- Read-only: current state of every row the follow-up release touches.
SELECT 'pub|' || id || '|' || name || '|' || country_id || '|' || feed_status || '|' || coalesce(domain,'') || '|' || homepage_url || '|' || coalesce(language,'') || '|' || source_type FROM publishers WHERE id IN (270, 8951) OR lower(domain) LIKE '%nbcnews%' OR lower(domain) LIKE '%tnx.africa%' OR lower(domain) LIKE '%sqoop%' OR lower(domain) LIKE '%people243%' OR lower(domain) LIKE '%mohalefm%';
SELECT 'feed|' || f.id || '|' || f.publisher_id || '|' || f.feed_type || '|' || f.feed_url || '|' || f.enabled || '|' || coalesce(f.last_status,'') || '|' || f.consecutive_failures || '|' || (SELECT count(*) FROM articles a WHERE a.feed_id = f.id) FROM feeds f WHERE f.publisher_id IN (270, 8951) OR f.feed_url LIKE '%nbcnews.na%';
SELECT 'sub|' || id || '|' || status || '|' || coalesce(publisher_id::text,'') || '|' || name || '|' || country_id || '|' || coalesce(feed_url,'') || '|' || coalesce(feed_type,'') || '|' || coalesce(ingestion_method,'') || '|' || coalesce(language,'') || '|' || coalesce(sitemap_url,'') || '|' || feed_verified || '|' || right(coalesce(verification_detail,''), 50) FROM publisher_submissions WHERE id IN (137, 161, 168, 169, 170, 171) ORDER BY id;
SELECT 'cand|' || id || '|' || domain || '|' || status || '|' || coalesce(promoted_submission_id::text,'') FROM discovered_sources WHERE id IN (382, 357, 425, 477, 314) OR promoted_submission_id IN (137, 161) ORDER BY id;
SELECT 'country|' || id || '|' || name FROM countries WHERE id IN (3, 78) OR id IN (SELECT country_id FROM publisher_submissions WHERE id BETWEEN 168 AND 171);
SELECT 'refs270|' || (SELECT count(*) FROM articles WHERE publisher_id = 270) || '|' || (SELECT count(*) FROM youtube_videos WHERE publisher_id = 270) || '|' || (SELECT count(*) FROM editorial_profiles WHERE publisher_id = 270);
SELECT 'cols|' || string_agg(column_name, ',' ORDER BY ordinal_position) FROM information_schema.columns WHERE table_name = 'feeds';
SELECT 'maxid|' || (SELECT max(id) FROM publishers) || '|' || (SELECT max(id) FROM feeds) || '|' || (SELECT max(id) FROM publisher_submissions);
